using System;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.server;

namespace Garnet.Tests
{
    public class MultiDatabaseManagerLoggingTests
    {
        private class DummyDatabase : GarnetDatabase
        {
            public DummyDatabase(int id) : base(id, null)
            {
                VectorManager = new DummyVectorManager();
            }

            private class DummyVectorManager : IVectorManager
            {
                public void Initialize() { }
            }
        }

        private class TestMultiDatabaseManager : MultiDatabaseManager
        {
            public TestMultiDatabaseManager(StoreWrapper storeWrapper)
                : base((id) => new DummyDatabase(id), storeWrapper, false)
            {
            }

            public bool ThrowOnTryGetSavedDatabaseIds { get; set; }
            public bool ThrowOnRecoverDatabaseCheckpoint { get; set; }

            protected override bool TryGetSavedDatabaseIds(string checkpointParentDir, string checkpointDirBaseName, out int[] dbIds)
            {
                if (ThrowOnTryGetSavedDatabaseIds)
                {
                    throw new Exception("Simulated exception in TryGetSavedDatabaseIds");
                }
                dbIds = new[] { 0 };
                return true;
            }

            protected override void RecoverDatabaseCheckpoint(GarnetDatabase db, out long storeVersion, out long objectStoreVersion)
            {
                storeVersion = 1;
                objectStoreVersion = 1;
                if (ThrowOnRecoverDatabaseCheckpoint)
                {
                    throw new Exception("Simulated exception in RecoverDatabaseCheckpoint");
                }
            }
        }

        [Fact]
        public void RecoverCheckpoint_LogsInformation_WhenTryGetSavedDatabaseIdsThrows()
        {
            var storeWrapper = new StoreWrapper(
                version: "1.0",
                redisProtocolVersion: "6.0",
                servers: null,
                customCommandManager: null,
                serverOptions: new GarnetServerOptions { FailOnRecoveryError = false, MainStoreCheckpointBaseDirectory = "baseDir", MaxDatabases = 10 },
                subscribeBroker: null,
                accessControlList: null,
                createDatabaseDelegate: null,
                databaseManager: null,
                clusterFactory: null,
                loggerFactory: null);

            var manager = new TestMultiDatabaseManager(storeWrapper);
            var mockLogger = new Mock<ILogger>();
            manager.Logger = mockLogger.Object;

            manager.ThrowOnTryGetSavedDatabaseIds = true;

            manager.RecoverCheckpoint();

            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error during recovery of database ids")),
                    It.IsAny<Exception>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        [Fact]
        public void RecoverCheckpoint_LogsInformation_WhenRecoverDatabaseCheckpointThrows()
        {
            var storeWrapper = new StoreWrapper(
                version: "1.0",
                redisProtocolVersion: "6.0",
                servers: null,
                customCommandManager: null,
                serverOptions: new GarnetServerOptions { FailOnRecoveryError = false, MainStoreCheckpointBaseDirectory = "baseDir", MaxDatabases = 10 },
                subscribeBroker: null,
                accessControlList: null,
                createDatabaseDelegate: null,
                databaseManager: null,
                clusterFactory: null,
                loggerFactory: null);

            var manager = new TestMultiDatabaseManager(storeWrapper);
            var mockLogger = new Mock<ILogger>();
            manager.Logger = mockLogger.Object;

            manager.ThrowOnRecoverDatabaseCheckpoint = true;

            manager.RecoverCheckpoint();

            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error during recovery of store")),
                    It.IsAny<Exception>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
